PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,email TEXT NOT NULL UNIQUE,name TEXT NOT NULL,password_hash TEXT NOT NULL,password_salt TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'user',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,sort_order INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS mods(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT 'عمومی',version TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL DEFAULT '',download_url TEXT NOT NULL,downloads INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'published',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS packs(id TEXT PRIMARY KEY,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',category TEXT NOT NULL DEFAULT 'پک',version TEXT NOT NULL DEFAULT '',image_url TEXT NOT NULL DEFAULT '',download_url TEXT NOT NULL,downloads INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'published',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS downloads(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,mod_id TEXT NOT NULL,downloaded_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(mod_id) REFERENCES mods(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS site_stats(id INTEGER PRIMARY KEY CHECK(id=1),users INTEGER NOT NULL DEFAULT 0,mods INTEGER NOT NULL DEFAULT 0,packs INTEGER NOT NULL DEFAULT 0,downloads INTEGER NOT NULL DEFAULT 0);
INSERT OR IGNORE INTO site_stats(id,users,mods,packs,downloads) VALUES(1,0,0,0,0);
